// Cache LRU : capacité fixe, éviction du moins récemment utilisé.
export function lruProcess(capacity, ops) {
  const map = new Map();
  const out = [];
  for (const op of ops) {
    if (op[0] === 'put') {
      // BUG : n'évince jamais et ne rafraîchit pas la récence.
      map.set(op[1], op[2]);
    } else if (op[0] === 'get') {
      out.push(map.has(op[1]) ? map.get(op[1]) : -1);
    }
  }
  return out;
}

